<?php declare(strict_types=1);namespace App\Controllers\Api;use App\Core\DB;use App\Core\Request;use App\Core\Response;use App\Models\Order;use App\Services\OrderService;use App\Services\StripeService;final class WebhookController{public function stripe(Request $i):Response{$E=$i->raw();$j=(string)$i->header('stripe-signature','');if(!StripeService::verifyWebhook($E,$j)){return Response::error('invalid_signature',400);}$a=json_decode($E,true);if(!is_array($a)||empty($a['id'])){return Response::error('invalid_payload',400);}if(DB::from('webhook_events')->where('event_id',(string)$a['id'])->count()>0){return Response::json(['ok'=>true,'duplicate'=>true]);}DB::insert('webhook_events',['provider'=>'stripe','event_id'=>(string)$a['id'],'type'=>(string)($a['type']??''),'payload'=>$a,'created_at'=>now()]);$g=(string)($a['type']??'');$c=$a['data']['object']??[];try{if(in_array($g,['checkout.session.completed','checkout.session.async_payment_succeeded'],true)){$m=(int)($c['metadata']['order_id']??$c['client_reference_id']??0);$D=$m?Order::find($m):null;if($D&&($c['payment_status']??'')==='paid'){OrderService::markPaid($D,'stripe',(string)($c['payment_intent']??$c['id']??''));}}elseif($g==='checkout.session.async_payment_failed'||$g==='checkout.session.expired'){$m=(int)($c['metadata']['order_id']??$c['client_reference_id']??0);if($m&&($u=Order::find($m))&&$u['status']==='pending'){Order::update($m,['status'=>$g==='checkout.session.expired'?'cancelled':'failed']);}}elseif($g==='charge.refunded'){$z=(string)($c['payment_intent']??'');if($z&&$u=Order::query()->where('payment_ref',$z)->first()){Order::update((int)$u['id'],['status'=>'refunded']);if($u['license_id']){\App\Services\LicenseService::setStatus(\App\Models\License::find((int)$u['license_id']),'suspended','refund');}}}DB::update('webhook_events',['processed_at'=>now()],'event_id = ?',[(string)$a['id']]);}catch(\Throwable $o){tp_log('stripe','webhook '.$g.' : '.$o->getMessage());return Response::error('processing_error'